/**
 * Crea el tema canónico tema-134: "Normativa: el Reglamento de Policía
 * Sanitaria Mortuoria" y lo asigna como Tema 16 (bloque-2, numero=18) de
 * la oposición Oficial Cementerio (Ayto. Zaragoza).
 *
 * Corresponde al TEMA 16 oficial del Anexo I (bases2110.pdf): "Normativa:
 * Reglamento de policía sanitaria mortuoria."
 *
 * Fuentes primarias verificadas mediante búsqueda en esta sesión de
 * trabajo:
 * - Decreto 2263/1974, de 20 de julio, por el que se aprueba el
 *   Reglamento de Policía Sanitaria Mortuoria (BOE-A-1974-1358) — norma
 *   estatal de base, que mantiene plena vigencia general según fuentes
 *   consultadas, complementada y modificada en lo no regulado
 *   específicamente por Aragón.
 * - Decreto 15/1987, de 16 de febrero, de la Diputación General de
 *   Aragón, por el que se regula el traslado de cadáveres en la
 *   Comunidad Autónoma de Aragón.
 * - Decreto 106/1996, de Aragón, que modificó parcialmente el Decreto
 *   2263/1974 para simplificar y agilizar trámites y requisitos
 *   administrativos en esta materia.
 *
 * No se ha localizado en esta sesión (ni se ha buscado exhaustivamente,
 * dado que no era el objeto de la búsqueda) un decreto autonómico
 * aragonés más reciente que sustituya por completo el marco de 1974,
 * por lo que se describe el contenido general del Reglamento de 1974 sin
 * atribuirle artículos o apartados numerados concretos no releídos
 * directamente en esta sesión.
 *
 * Tres secciones:
 * 1. objeto-ambito-autoridades-mortuoria
 * 2. practicas-sanitarias-plazos-cadaveres
 * 3. traslados-exhumaciones-normativa-aragon
 *
 * Uso: node --env-file=.env.local scripts/seed-tema-134-reglamento-policia-sanitaria-mortuoria.mjs
 */
const URL_BASE = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!URL_BASE || !SERVICE_KEY) {
  console.error("❌ Faltan NEXT_PUBLIC_SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const HEADERS = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json" };
const TEMA = "tema-134";
const OPOSICION = "oficial-cementerio-ayto-zaragoza";
